import {chromium} from 'playwright';import fs from 'fs';
fs.mkdirSync('character-story-final-renders',{recursive:true});const browser=await chromium.launch({headless:true});const ctx=await browser.newContext({viewport:{width:390,height:844}});const page=await ctx.newPage();const errors=[];
page.on('pageerror',e=>errors.push('page:'+e.message));page.on('console',m=>{if(m.type()==='error')errors.push('console:'+m.text())});page.on('requestfailed',r=>{const u=r.url(),e=r.failure()?.errorText||'';if(/\.(?:mp3|wav|ogg|m4a)($|\?)/.test(u)&&/ERR_ABORTED/.test(e))return;errors.push('request:'+u+':'+e)});const ok=(c,m)=>{if(!c)throw new Error(m)};
await page.goto('http://127.0.0.1:8144/',{waitUntil:'domcontentloaded'});await page.waitForTimeout(180);await page.evaluate(()=>localStorage.removeItem('latchlings_story_cards_seen_v1'));
await page.evaluate(()=>startLevel(1));await page.waitForTimeout(145);ok(await page.locator('#storyCardOverlay.show').count()===0,'Story card appeared before screen swipe could clear');await page.waitForTimeout(175);ok(await page.locator('#storyCardOverlay.show').count()===1,'Story card did not appear after refined delay');
const state=await page.evaluate(()=>({featured:document.getElementById('storyCardOverlay').dataset.featured,portrait:document.querySelector('#storyCardScene .story-scene-character')?.dataset.character,filter:getComputedStyle(document.getElementById('storyCardPanel')).filter,scrollW:document.documentElement.scrollWidth,innerW:innerWidth}));ok(state.featured==='Pippa'&&state.portrait==='Pippa','Pippa portrait missing after auto-open');ok(state.scrollW<=state.innerW+1,'Overflow after auto story');await page.screenshot({path:'character-story-final-renders/pippa-auto-after-swipe.png',fullPage:true});
await page.evaluate(()=>{window.LatchlingsStoryTheme.close(false);window.LatchlingsStoryTheme.show(53,true)});await page.waitForTimeout(80);await page.screenshot({path:'character-story-final-renders/pip-tansy-final.png',fullPage:true});ok(errors.length===0,'Browser errors: '+errors.join(' | '));console.log('CHARACTER_STORY_TIMING_OK',JSON.stringify(state));await browser.close();
